// Custom Worker entry (wrangler.jsonc `main`): drops scanner probes, serves the 404
// page for unknown addresses, hands everything else to the OpenNext-generated worker.
// https://opennext.js.org/cloudflare/howtos/custom-worker
import { isBotProbe, probeResponse } from "./bot-filter";
import { resolveRoute } from "./page-routes";
// `.open-next/worker.js` is generated by `opennextjs-cloudflare build`, so it is missing
// in a fresh clone: @ts-expect-error would fail whenever it exists.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { default as handler } from "../.open-next/worker.js";
// Generated by scripts/build-static-404.mjs right after the OpenNext build (same reason).
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { ro as notFoundRo, en as notFoundEn, pages } from "../.open-next/static-404.mjs";

const PAGES: ReadonlySet<string> = new Set(pages as string[]);

// The styled 404 page, prerendered at build: answering with it costs no rendering.
function notFoundPage(method: string, pathname: string): Response {
  const html: string = /^\/en(\/|$)/.test(pathname) ? notFoundEn : notFoundRo;
  return new Response(method === "HEAD" ? null : html, {
    status: 404,
    headers: {
      "content-type": "text/html; charset=utf-8",
      // These skip next.config.ts headers(). The page has no scripts, so none may run.
      "content-security-policy":
        "default-src 'self'; script-src 'none'; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; font-src 'self'; base-uri 'self'; form-action 'self'; frame-ancestors 'self'",
      "x-content-type-options": "nosniff",
      "referrer-policy": "strict-origin-when-cross-origin",
      // Lets Workers Cache answer repeat hits without running the Worker. Its key includes
      // the Worker version, so a path that becomes a page in a later deploy is not stuck.
      "cache-control": "public, s-maxage=60",
    },
  });
}

const worker = {
  fetch(request: Request, env: unknown, ctx: unknown) {
    const url = new URL(request.url);
    if (isBotProbe(request.method, url.pathname)) {
      return probeResponse(request.method);
    }
    // Applies to www too: its real pages still reach the middleware, which 301s to the apex.
    const route = resolveRoute(url.pathname, PAGES);
    if (route.type === "redirect") {
      return Response.redirect(new URL(route.location + url.search, url).toString(), 308);
    }
    if (route.type === "not-found") {
      return notFoundPage(request.method, url.pathname);
    }
    return handler.fetch(request, env, ctx);
  },
};

export default worker;

// Re-exported Durable Object classes, as in the generated worker (same reason as above).
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "../.open-next/worker.js";
